import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百八十六章 从眼睛中解脱出来","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/186第一百八十六章 从眼睛中解脱出来.md","filePath":"meditation/巴利文大藏经/186第一百八十六章 从眼睛中解脱出来.md"}'),o={name:"meditation/巴利文大藏经/186第一百八十六章 从眼睛中解脱出来.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第一百八十六章-从眼睛中解脱出来" tabindex="-1">第一百八十六章 从眼睛中解脱出来 <a class="header-anchor" href="#第一百八十六章-从眼睛中解脱出来" aria-label="Permalink to &quot;第一百八十六章 从眼睛中解脱出来&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>18.(7).罗侯罗相应</p><p>1.第一品</p><p>相应部18相应1经/眼经(罗侯罗相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，罗侯罗尊者来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，罗侯罗尊者对佛陀说：“世尊，请您教导给我一个简单易行的修行方法，让我在独自修行的时候能够保持内心的清净，让我能够由此管束好自己的行为、言语、念想，让我的行为、言语、念想不会肆意妄为、胡作非为。让我能够精进努力的去修行。世尊如果您能够教导给我这样一个简单易行的修行方法那就很好了。”</p><p>佛陀说：“罗侯罗！你是怎么想的？眼睛看见的事物是永远保持不变，永恒存在的，还是随时在变化，无法永恒存在的？”</p><p>罗侯罗尊者回答：“世尊，我眼睛看见的事物随时都在变化，无法永远保持不变，无法永恒的存在。”</p><p>佛陀说：“罗侯罗！既然如此，那么你认为如何？你眼睛看见的这些事物给你带来的是快乐，还是痛苦？”</p><p>罗侯罗尊者回答：“世尊，我眼睛看见的这些事物最终给我带来的都是痛苦，为什么这么说呢？因为就算这些事物给我带来了快乐，那都是短暂的。世间一切的事物随时都在变化，无法永远的保持不变，无法永恒的存在，一旦这些事物衰败、灭亡、消失，那么之前这些事物给我带来了多少的快乐，当这些事物衰败、灭亡、消失的时候就会给我带来多少痛苦，所以我说世间的事物给我带来的最终都是痛苦。”</p><p>佛陀说：“罗侯罗！既然你眼睛看见的事物是随时在变化的，是无法永远保持不变的，是无法永恒存在的，是最终给自己带来痛苦的，那么你还会认为：「这些事物是我所拥有的；我就是这个精神思想和物质身体的结合体；这个精神思想和物质身体就是永恒不变、真实的我。」吗？你还会有这样的想法吗？罗侯罗！简单的说，你还会认为：「这是我的，我就是这个，这个就是真实不变的我。」吗？”</p><p>罗侯罗尊者回答：“世尊，我不会认为世间的事物是我所拥有的，因为世间的事物随时都在变化，它们会衰败、灭亡、消失，我无法永恒的拥有它们，我不过是暂时的管理它们而已，而我这个在世间的物质身体和精神思想也是随时在变化的。我的物质身体会生病、衰老、死亡，我的精神思想也随时都在变化，无法永远保持不变，无法永恒的存在。当我死去的那一刻，我的物质身体和精神思想全部都会灭尽、消失。我的物质身体会腐烂，我的精神思想会随着我的死亡而熄灭、消失。一旦我死去，我的物质身体和精神思想就全部都不存在了，所以我不是世间这个精神思想和物质身体的结合体。这个精神思想和物质身体也不是真实不变的我，如果它们是真实不变的我，那我就应该青春永驻、永远不死，可是世间每一个人都会衰老，最后都会死去。包括世间的圣者在内，他们在世间的物质身体和精神思想也如同陶瓷器具一样的脆弱，随时都会被打破。这些在世间修行的圣者，他们的物质身体都会生病、衰老、死亡，他们的精神思想都会在死后熄灭、消失，世间没有任何一个人可以永远的青春永驻、永远不死，所以这个精神思想和物质身体不是永恒不变、真实的我。”</p><p>佛陀说：“罗侯罗！你是怎么想的？耳朵听见的声音，鼻子闻到的气味，舌头尝到的味道，身体触摸事物产生的触觉或身体感觉到的环境变化（冷热、舒适等等），内心生起的念想是永远保持不变，永恒存在的，还是随时都在变化，无法永恒存在的？”</p><p>罗侯罗尊者回答：“世尊，我耳朵听见的声音，鼻子闻到的气味，舌头尝到的味道，身体触摸事物产生的触觉或身体感觉到的环境变化（冷热、舒适等等），内心生起的念想随时都在变化，无法永远保持不变，无法永恒的存在。”</p><p>佛陀说：“罗侯罗！既然如此，那么你认为如何？你耳朵听见的声音，鼻子闻到的气味，舌头尝到的味道，身体触摸事物产生的触觉或身体感觉到的环境变化（冷热、舒适等等），内心生起的念想是给你带来快乐的，还是给你带来痛苦的？”</p><p>罗侯罗尊者回答：“世尊，我耳朵听见的声音，鼻子闻到的气味，舌头尝到的味道，身体触摸事物产生的触觉或身体感觉到的环境变化（冷热、舒适等等），内心生起的念想最终给我带来的都是痛苦，为什么这么说呢？因为就算声音、气味、味道、触觉、环境感觉、念想给我带来了快乐，那都是短暂的，声音、气味、味道、触摸的事物、环境、念想随时都在变化，无法永远的保持不变，无法永恒的存在，一旦这些声音、气味、味道、触摸的事物、环境、念想消退、灭尽、消失，那么之前这些声音、气味、味道、触觉、环境感觉、念想给我带来了多少的快乐，当这些声音、气味、味道、触摸的事物、环境、念想消退、灭尽、消失的时候就会给我带来多少痛苦，所以我说声音、气味、味道、触摸的事物、环境、念想给我带来的最终都是痛苦。”</p><p>佛陀说：“罗侯罗！既然你耳朵听见的声音，鼻子闻到的气味，舌头尝到的味道，身体触摸事物产生的触觉或身体感觉到的环境变化（冷热、舒适等等），内心生起的念想是随时在变化的，是无法永远保持不变的，是无法永恒存在的，是最终给自己带来痛苦的，那么你还会认为：「这些声音、气味、味道、触觉、环境感觉、念想是我所拥有的；我就是这个精神思想和物质身体的结合体；这个精神思想和物质身体就是永恒不变、真实的我。」吗？你还会有这样的想法吗？罗侯罗！简单的说，你还会认为：「这是我的，我就是这个，这个就是真实不变的我。」吗？”</p><p>罗侯罗尊者回答：“世尊，我不会认为声音、气味、味道、触觉、环境感觉、念想是我所拥有的，因为声音、气味、味道、触摸的事物、环境、念想随时都在变化，它们会消退、灭尽、消失，我无法永恒的拥有它们，我不过是暂时的接触它们而已，而我这个在世间的物质身体和精神思想也是随时在变化的，我的物质身体会生病、衰老、死亡，我的精神思想也随时都在变化，无法永远保持不变，无法永恒的存在。当我死去的那一刻，我的物质身体和精神思想全部都会灭尽、消失。我的物质身体会腐烂，我的精神思想会随着我的死亡而熄灭、消失。一旦我死去，我的物质身体和精神思想就全部都不存在了，所以我不是世间这个精神思想和物质身体的结合体。这个精神思想和物质身体也不是真实不变的我，如果它们是真实不变的我，那我就应该青春永驻、永远不死，可是世间每一个人都会衰老，最后都会死去。包括世间的圣者在内，他们在世间的物质身体和精神思想也如同陶瓷器具一样的脆弱，随时都会被打破，这些在世间修行的圣者，他们的物质身体都会生病、衰老、死亡，他们的精神思想都会在死后熄灭、消失，世间没有任何一个人可以永远的青春永驻、永远不死，所以这个精神思想和物质身体不是永恒不变、真实的我。”</p><p>佛陀说：“罗侯罗！你已经明白了如来的正法，罗侯罗！已经受到如来教导的圣弟子们，他们将会逐渐的除灭对世间一切物质事物的贪欲，他们将会逐渐的除灭对一切声音、气味、味道、触觉、环境感觉、念想的贪欲。他们不会再去执着和挂念眼睛看见的事物，不会再去执着和挂念耳朵听到的声音，不会再去执着和挂念鼻子闻到的气味，不会再去执着和挂念舌头尝到的味道，不会再去执着和挂念身体触摸事物产生的触觉，不会再去执着和挂念身体感觉到的环境变化（冷热、舒适等等），不会再去执着和挂念内心生起的念想。他们从世间一切的事物中解脱出来，他们从一切的声音、气味、味道、触觉、环境感觉、念想中解脱出来，他们由此证悟了解脱的智慧，证悟了解脱的果位，他们彻底的明白：「从这一世开始已经不会再次的出生在世间。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有轮回的状态，不会再出生在世间了」。”</p><p>佛陀说法后，罗侯罗尊者再次的顶礼佛陀，他随喜赞叹佛陀说法的无量功德，并按着佛陀所说的法去修行。</p>',20)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
